            lo = mid + 1
        else:
            hi = mid - 1
    return -1

print(search_buggy([4], 4))

def hang(nums, target):
    lo = 0
    hi = len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid
        else:
            hi = mid - 1
    return lo

def first_at_least(nums, target):
    lo = 0
    hi = len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

print(first_at_least([1, 2, 2, 2, 3], 2))
